import os
import sys
import numpy as np
import pandas as pd
from collections import defaultdict
from sklearn.model_selection import train_test_split
import glob
import re

# Suppress warnings
warnings.filterwarnings("ignore")


def find_training_files(input_dir="./input"):
    """Find training files by scanning input directory"""
    csv_files = glob.glob(os.path.join(input_dir, "*.csv"))

    # Identify which is training by checking column names
    train_data = None
    test_data = None
    sample_data = None

    for f in sorted(csv_files):
        try:
            df = pd.read_csv(f)
            if "before" in df.columns and "after" in df.columns:
                if "test" in f.lower() and ("sample" not in f.lower()):
                    test_data = df
                    break
                elif "train" in f.lower():
                    train_data = df
                    break
                elif "sample" in f.lower():
                    sample_data = df
        except Exception:
            continue

    if train_data is None and sample_data is None:
        # Fallback: try to find any file with both columns
        for f in sorted(csv_files):
            try:
                df = pd.read_csv(f)
                if "before" in df.columns and "after" in df.columns:
                    train_data = df
                    sample_data = df
                    break
            except:
                continue

    return train_data, test_data, sample_data


def find_test_files(input_dir="./input"):
    """Find test files by scanning input directory"""
    csv_files = glob.glob(os.path.join(input_dir, "*.csv"))

    test_data = None
    sample_data = None

    for f in sorted(csv_files):
        try:
            df = pd.read_csv(f)
            if (
                "before" not in df.columns
            ):  # Test set typically has no 'before' normalized
                if "test" in f.lower():
                    test_data = df
                    break
                elif "sample" in f.lower():
                    sample_data = df
        except Exception:
            continue

    return test_data, sample_data


